                      ✕
                    </button>
                  </li>
                ))}
              </ul>
            </section>
          )}

          <section>
            <h3 className={h}>Crew</h3>
            {!lists ? (
              <div className="h-20 animate-pulse rounded-2xl bg-white/5" />
            ) : lists.friends.length === 0 ? (
              <p className="text-[14px] text-ink/60">
                No crew yet. Share your QR code or add a friend by handle.
