import { NextResponse } from "next/server";
import { BUILDING_WIKI } from "@/lib/buildingWiki";

type History = { title: string; extract: string; url: string; note?: string };
const cache = new Map<string, { at: number; value: History | null }>();
const WEEK = 7 * 24 * 3600 * 1000;

/** Sourced history for a campus building: Wikipedia summary (first 3 sentences) + link, cached. */
export async function GET(req: Request) {
  const name = new URL(req.url).searchParams.get("name") ?? "";
  const entry = BUILDING_WIKI[name];
  if (!entry) return NextResponse.json({ history: null });

  const hit = cache.get(entry.title);
  if (hit && Date.now() - hit.at < WEEK) return respond(hit.value, entry.note);

  try {
    const res = await fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(entry.title.replace(/ /g, "_"))}`, {
      headers: { "user-agent": "mustang-city/0.1 (campus exploration game)" },
    });
    if (!res.ok) throw new Error(String(res.status));
    const d = (await res.json()) as { title?: string; extract?: string; type?: string; content_urls?: { desktop?: { page?: string } } };
    const sentences = (d.extract ?? "").split(/(?<=[.!?])\s+/).slice(0, 3).join(" ");
    const value = d.type === "disambiguation" || !sentences ? null : { title: d.title ?? entry.title, extract: sentences, url: d.content_urls?.desktop?.page ?? "" };
    cache.set(entry.title, { at: Date.now(), value });
    return respond(value, entry.note);
  } catch {
    return NextResponse.json({ history: null, error: "unavailable" }, { status: 200 });
  }
}

function respond(history: History | null, note?: string) {
  return NextResponse.json(
    { history: history ? { ...history, note } : null },
    { headers: { "cache-control": "public, s-maxage=604800, stale-while-revalidate=86400" } },
  );
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import { MISSIONS, TYPE_LABEL, CATEGORY_LABEL } from "@/lib/missions";
import { distanceM } from "@/lib/geo";
import { isRevealedAt } from "@/lib/fog";
import { getServerSnapshot, getSnapshot, subscribe } from "@/lib/progress";
import type { BuildingTap } from "../map/MapView";
import { TYPE_COLOR } from "../missions/MissionList";

type History = { title: string; extract: string; url: string; note?: string };

type Props = {
  building: BuildingTap;
  routed: { distanceM: number; minutes: number } | null;
  onWaypoint: (on: boolean) => void;
  onOpenMission: (slug: string) => void;
};

export default function BuildingDetail({ building, routed, onWaypoint, onOpenMission }: Props) {
  const { completions } = useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
  const [history, setHistory] = useState<History | null | "loading">(building.name ? "loading" : null);

  useEffect(() => {
    if (!building.name) return;
    let alive = true;
    fetch(`/api/building?name=${encodeURIComponent(building.name)}`)
      .then((r) => r.json())
      .then((j: { history: History | null }) => alive && setHistory(j.history))
      .catch(() => alive && setHistory(null));
    return () => {
      alive = false;
    };
  }, [building.name]);

  const explored = isRevealedAt(building.center[1], building.center[0]);
  const here = MISSIONS.filter((m) => distanceM(m.lngLat, building.center) <= 90);
  const h = "mb-2 text-[12px] font-bold tracking-[0.16em] text-ink/55 uppercase";

  return (
    <div className="space-y-5 pb-4">
      <div className="flex items-center gap-2 text-[12px] font-bold tracking-[0.14em] uppercase">
        <span className="text-teal">Mustang City</span>
        <span className="text-ink/30">·</span>
        <span className={explored ? "text-gold" : "text-ink/50"}>{explored ? "Explored" : "Still in the fog"}</span>
      </div>

      {!building.name && <p className="text-[14px] text-ink/60">This building isn&apos;t named on the map yet.</p>}

      {history === "loading" && <div className="h-24 animate-pulse rounded-2xl bg-white/5" />}
      {history && history !== "loading" && (
        <section className="rounded-2xl border border-white/10 bg-white/[0.04] p-4">
          <p className="text-[11px] font-bold tracking-[0.16em] text-gold uppercase">{history.note ?? "History"}</p>
          <p className="mt-1.5 text-[14px] leading-snug text-ink/85">{history.extract}</p>
          {history.url && (
            <a href={history.url} target="_blank" rel="noreferrer" className="mt-2 inline-block text-[12px] font-semibold text-teal underline">
              Source: Wikipedia — {history.title}
            </a>
          )}
        </section>
      )}

      <section>
        <h3 className={h}>Missions here</h3>
        {here.length === 0 ? (
          <p className="text-[14px] text-ink/60">No jobs from The Goose at this building. Yet.</p>
        ) : (
          <ul className="space-y-2">
            {here.map((m) => {
              const kind = m.category ? "landmark" : m.type;
              return (
                <li key={m.slug}>
                  <button type="button" onClick={() => onOpenMission(m.slug)} className="flex w-full items-center gap-3 rounded-2xl bg-white/[0.05] p-3 text-left">
                    <span className="min-w-0 flex-1">
                      <span className={`block text-[11px] font-bold tracking-[0.14em] uppercase ${TYPE_COLOR[kind]}`}>
                        {m.category ? CATEGORY_LABEL[m.category] : TYPE_LABEL[m.type]}
                      </span>
                      <span className="block truncate text-[15px] font-bold text-ink">{m.title}</span>
                    </span>
                    <span className={`text-[13px] font-bold ${completions[m.slug] ? "text-teal" : "text-orange"}`}>
                      {completions[m.slug] ? "✓ Done" : `+${m.rep}`}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </section>

      <section className="rounded-2xl border border-dashed border-white/15 p-4">
        <p className="text-[11px] font-bold tracking-[0.16em] text-ink/55 uppercase">Classes here</p>
        <p className="mt-1 text-[14px] text-ink/70">Coming with Class Run: add your schedule and your classes in this building show up here, with waypoints and Rep for getting there on time.</p>
      </section>

      <button
        type="button"
        onClick={() => onWaypoint(!routed)}
        className="flex min-h-[52px] w-full items-center justify-center rounded-2xl border border-white/12 bg-white/[0.06] text-[16px] font-bold tracking-wide text-ink uppercase"
      >
        {routed ? `Clear waypoint · ${Math.round(routed.distanceM / 10) * 10} m · ${routed.minutes} min` : "Set waypoint"}
      </button>
    </div>
  );
}

